(function () {
'use strict';
var root = document.documentElement;
var reduceMotion = window.matchMedia &&
window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var animOff = document.body.classList.contains('anim-off');
if (reduceMotion || animOff || !('IntersectionObserver' in window)) {
revealEverything();
return;
}
root.classList.add('anim-ready');
document.addEventListener('DOMContentLoaded', init);
if (document.readyState !== 'loading') init();
var started = false;
function init() {
if (started) return;
started = true;
autoTag();
setupReveal();
setupCounters();
setupParallax();
setupTextReveal();
}
function autoTag() {
document.querySelectorAll('.section-header').forEach(function (el) {
if (!el.hasAttribute('data-anim')) el.setAttribute('data-anim', 'up');
});
var grids = [
'.card-grid', '.news-grid', '.events-grid', '.faculty-grid',
'.gallery-grid', '.albums-grid', '.testimonials-grid', '.videos-grid',
'.steps-grid', '.doc-grid'
];
grids.forEach(function (sel) {
document.querySelectorAll(sel).forEach(function (grid) {
var kids = grid.children;
for (var i = 0; i < kids.length; i++) {
var k = kids[i];
if (k.hasAttribute('data-anim')) continue;
k.setAttribute('data-anim', 'up');
k.setAttribute('data-anim-delay', String(Math.min(i, 6) * 90));
}
});
});
document.querySelectorAll('.split').forEach(function (split) {
var kids = split.children;
if (kids[0] && !kids[0].hasAttribute('data-anim')) kids[0].setAttribute('data-anim', 'right');
if (kids[1] && !kids[1].hasAttribute('data-anim')) kids[1].setAttribute('data-anim', 'left');
});
}
function setupReveal() {
var targets = document.querySelectorAll('[data-anim]');
if (!targets.length) return;
var io = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (!entry.isIntersecting) return;
var el = entry.target;
var delay = parseInt(el.getAttribute('data-anim-delay') || '0', 10);
if (delay) el.style.transitionDelay = (delay / 1000) + 's';
el.classList.add('is-visible');
if (!el.hasAttribute('data-anim-repeat')) io.unobserve(el);
});
}, { threshold: 0.12, rootMargin: '0px 0px -8% 0px' });
targets.forEach(function (el) {
var r = el.getBoundingClientRect();
if (r.top < window.innerHeight && r.bottom > 0) {
requestAnimationFrame(function () { el.classList.add('is-visible'); });
} else {
io.observe(el);
}
});
}
function setupCounters() {
var counters = document.querySelectorAll('[data-count-to]');
if (!counters.length) return;
var io = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (!entry.isIntersecting) return;
runCounter(entry.target);
io.unobserve(entry.target);
});
}, { threshold: 0.4 });
counters.forEach(function (el) { io.observe(el); });
}
function runCounter(el) {
var target = parseFloat(el.getAttribute('data-count-to')) || 0;
var prefix = el.getAttribute('data-count-prefix') || '';
var suffix = el.getAttribute('data-count-suffix') || '';
var decimals = (String(target).split('.')[1] || '').length;
var duration = 1600;
var startTime = null;
function easeOutExpo(t) { return t === 1 ? 1 : 1 - Math.pow(2, -10 * t); }
function frame(now) {
if (startTime === null) startTime = now;
var progress = Math.min((now - startTime) / duration, 1);
var value = target * easeOutExpo(progress);
el.textContent = prefix + formatNumber(value, decimals) + suffix;
if (progress < 1) {
requestAnimationFrame(frame);
} else {
el.textContent = prefix + formatNumber(target, decimals) + suffix;
}
}
requestAnimationFrame(frame);
}
function formatNumber(n, decimals) {
return decimals > 0
? n.toFixed(decimals)
: Math.round(n).toLocaleString();
}
function setupParallax() {
if (window.innerWidth < 900 || 'ontouchstart' in window) return;
var layers = document.querySelectorAll('[data-parallax]');
if (!layers.length) return;
var ticking = false;
function update() {
var vh = window.innerHeight;
layers.forEach(function (el) {
var speed = parseFloat(el.getAttribute('data-parallax')) || 0.2;
var rect = el.getBoundingClientRect();
if (rect.bottom < 0 || rect.top > vh) return;
var offset = (rect.top + rect.height / 2 - vh / 2) * speed * -1;
el.style.transform = 'translate3d(0,' + offset.toFixed(1) + 'px,0)';
});
ticking = false;
}
window.addEventListener('scroll', function () {
if (!ticking) { requestAnimationFrame(update); ticking = true; }
}, { passive: true });
update();
}
function setupTextReveal() {
var els = document.querySelectorAll('[data-text-reveal]');
if (!els.length) return;
els.forEach(function (el) {
var words = el.textContent.trim().split(/\s+/);
el.textContent = '';
words.forEach(function (word, i) {
var span = document.createElement('span');
span.className = 'tr-word';
span.textContent = word;
span.style.transitionDelay = (i * 0.05) + 's';
el.appendChild(span);
el.appendChild(document.createTextNode(' '));
});
});
var io = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (!entry.isIntersecting) return;
entry.target.querySelectorAll('.tr-word').forEach(function (w) {
w.classList.add('is-visible');
});
io.unobserve(entry.target);
});
}, { threshold: 0.3 });
els.forEach(function (el) { io.observe(el); });
}
function revealEverything() {
document.querySelectorAll('[data-anim], .tr-word').forEach(function (el) {
el.classList.add('is-visible');
});
}
})();